import React, { useState, useEffect } from "react";
import { getNotes, createNote, updateNote, deleteNote } from "./api";
import "./App.css";

function App() {
  const [notes, setNotes] = useState([]);
  const [newNote, setNewNote] = useState("");
  const [editingNoteId, setEditingNoteId] = useState(null);
  const [editingNoteContent, setEditingNoteContent] = useState("");
  const [showArchived, setShowArchived] = useState(false);

  // Cargar notas al iniciar
  useEffect(() => {
    loadNotes();
  }, []);

  // Función para cargar las notas
  const loadNotes = async () => {
    const data = await getNotes();
    setNotes(data);
  };

  // Agregar una nueva nota
  const handleAddNote = async () => {
    if (newNote.trim() === "") return;

    try {
      const newNoteData = {
        title: "Nueva nota",
        content: newNote,
        archived: false,
      };

      await createNote(newNoteData);
      setNewNote("");
      await loadNotes();
    } catch (error) {
      console.error("❌ Error al agregar la nota:", error);
    }
  };

  // Editar una nota
  const handleEditNote = async (id, newContent) => {
    try {
      await updateNote(id, { content: newContent });
      setEditingNoteId(null); // Salir del modo edición
      await loadNotes();
    } catch (error) {
      console.error("❌ Error al editar la nota:", error);
    }
  };

  // Eliminar una nota
  const handleDeleteNote = async (id) => {
    await deleteNote(id);
    await loadNotes();
  };

  // Archivar/Desarchivar una nota
  const handleArchiveNote = async (id, archived) => {
    await updateNote(id, { archived: !archived });
    await loadNotes();
  };

  // Filtrar notas activas o archivadas
  const filteredNotes = showArchived
    ? notes.filter(note => note.archived)
    : notes.filter(note => !note.archived);

  return (
    <div className="container">
      <h1>Notas</h1>

      {/* Agregar una nueva nota */}
      <input
        value={newNote}
        onChange={(e) => setNewNote(e.target.value)}
        placeholder="Escribe una nota"
      />
      <button onClick={handleAddNote}>Agregar Nota</button>

      {/* Botón para alternar entre notas activas y archivadas */}
      <button onClick={() => setShowArchived(!showArchived)}>
        {showArchived ? "Ver Notas Activas" : "Ver Notas Archivadas"}
      </button>

      {/* Lista de notas */}
      <h2>{showArchived ? "Notas Archivadas" : "Notas Activas"}</h2>
      <ul>
        {filteredNotes.map((note) => (
          <li key={note.id}>
            {editingNoteId === note.id ? (
              // Modo edición
              <>
                <input
                  value={editingNoteContent}
                  onChange={(e) => setEditingNoteContent(e.target.value)}
                />
                <button onClick={() => handleEditNote(note.id, editingNoteContent)}>
                  Guardar
                </button>
                <button onClick={() => setEditingNoteId(null)}>Cancelar</button>
              </>
            ) : (
              // Modo visualización
              <>
                {note.content}
                <button onClick={() => handleArchiveNote(note.id, note.archived)}>
                  {note.archived ? "Desarchivar" : "Archivar"}
                </button>
                <button onClick={() => handleDeleteNote(note.id)}>🗑</button>
                <button
                  onClick={() => {
                    setEditingNoteId(note.id);
                    setEditingNoteContent(note.content);
                  }}
                >
                  Editar
                </button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
